//! Askama template contexts. Output is HTML-escaped by default; only `svg` (generated by us) is `|safe`.

use crate::{AppState, auth::Staff, error::AppError};
use askama::Template;
use axum::response::Html;

pub struct Ctx {
    pub outlet: String,
    pub role: String,
    pub user: String,
    pub nav: &'static str,
}

impl Ctx {
    pub async fn staff(st: &AppState, s: &Staff, nav: &'static str) -> Result<Self, AppError> {
        Ok(Self {
            outlet: outlet_name(st).await?,
            role: s.role.as_str().into(),
            user: s.name.clone(),
            nav,
        })
    }
    pub async fn guest(st: &AppState) -> Result<Self, AppError> {
        Ok(Self {
            outlet: outlet_name(st).await?,
            role: String::new(),
            user: String::new(),
            nav: "",
        })
    }
}

async fn outlet_name(st: &AppState) -> Result<String, AppError> {
    Ok(
        sqlx::query_scalar("SELECT outlet_name FROM outlet_settings WHERE id = 1")
            .fetch_one(&st.db)
            .await?,
    )
}

pub fn render<T: Template>(t: T) -> Result<Html<String>, AppError> {
    Ok(Html(t.render().map_err(|e| anyhow::anyhow!("template: {e}"))?))
}

